From 895a87fee605d6c271c4f34f887237040b985371 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:14:35 +0100
Subject: [PATCH] faces/ConfigSensors: show the new label after renaming a
 sensor

Renaming a sensor with the pencil in Sensors Details kept showing the
old name, because the label was changed inside the existing object and
the chip never saw a new value. Assign a new object with the new label.

BUG: 527464
---
 faces/ConfigSensors.qml | 9 +++------
 1 file changed, 3 insertions(+), 6 deletions(-)

diff --git a/faces/ConfigSensors.qml b/faces/ConfigSensors.qml
index 86c0c6ba..a3d58f48 100644
--- a/faces/ConfigSensors.qml
+++ b/faces/ConfigSensors.qml
@@ -141,8 +141,7 @@ ColumnLayout {

         onSelectedChanged: root.cfg_totalSensors = selected
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.cfg_sensorLabels = Object.assign({}, root.cfg_sensorLabels, {[sensorId]: label})
         }
     }

@@ -167,8 +166,7 @@ ColumnLayout {
             root.cfg_sensorColorsChanged();
         }
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.cfg_sensorLabels = Object.assign({}, root.cfg_sensorLabels, {[sensorId]: label})
         }
     }

@@ -185,8 +183,7 @@ ColumnLayout {

         onSelectedChanged: root.cfg_lowPrioritySensorIds = selected
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.cfg_sensorLabels = Object.assign({}, root.cfg_sensorLabels, {[sensorId]: label})
         }
     }

